  1	import React, { useEffect, useState } from 'react';
  2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
  3	import { ZimmLogo } from 'app/components/ui-kits/atoms/zimmLogo';
  4	import { ZimmSubscribeSection } from 'app/components/ui-kits/organisms/zimmSubscribeSection';
  5	import { noop } from '@salesforce/retail-react-app/app/utils/utils';
  6	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
  7	import { useHistory } from 'react-router-dom';
  8	import { HOME_HREF } from '@salesforce/retail-react-app/app/constants';
  9	import { useContentfulClient } from 'app/hooks/useContentfulClient';
 10	import { filterByRegion, pickMostSpecificByRegion } from 'app/utils/resolveByRegion';
 11	import type { FooterConfigEntry, FooterNavGroupEntry, LinkEntry } from 'app/types/contentful';
 12	import { FooterNavColumn } from './footerNavColumn';
 13	import { BottomBar } from './bottomBar';
 14	
 15	const ZIMM_FOOTER_RECIPE = 'ZimmFooter';
 16	
 17	// Contentful resolves nested references `include` levels deep, and the footer model is exactly
 18	// three: footerConfig → navGroups (1) → links (2) → regions (3). Depth 3 is the minimum that
 19	// populates `entry.fields.regions[].fields.siteId`, which isEligible reads.
 20	//
 21	// Getting this wrong fails hard, not gracefully. At 2, a region-scoped link's `regions` array
 22	// arrives as unresolved link stubs with no `fields` (the SDK keeps unresolvable links by default
 23	// — `withoutUnresolvableLinks` is not passed), so `region.fields.siteId` throws, the `.catch`
 24	// below swallows it, footerData stays null and the *entire* footer renders nothing — columns,
 25	// logo band and bottom bar included. Not a house default either: useContentful.ts hardcodes 2
 26	// for asset resolution, per its own comments, which is a different concern.
 27	const FOOTER_INCLUDE_DEPTH = 3;
 28	
 29	// ---------------------------------------------------------------------------
 30	// Types
 31	// ---------------------------------------------------------------------------
 32	type FooterProps = {
 33	  /** Contentful FooterConfigEntry. Pass FOOTER_FIXTURE from index.stories.content.ts in stories/tests. */
 34	  data: FooterConfigEntry;
 35	  copyrightYear?: number;
 36	  /** Forces SubscribeSection into its post-submit state. For Storybook/tests only. */
 37	  initialSubscribed?: boolean;
 38	  /**
 39	   * Opt in to the HPC-035 first/last-name capture modal. Defaults to false: SFCC-55 ships the
 40	   * Stay in Touch section as an input plus submit button only, and the modal has no design yet.
 41	   */
 42	  enableNameCapture?: boolean;
 43	  /** Click handler for the wordmark. Mirrors the header's onLogoClick prop, defaulting to
 44	   *  noop so the presentational Footer never navigates on its own. */
 45	  onLogoClick?: () => void;
 46	  /** href for the Privacy Policy link inside the subscribe modal (HPC-037). Locale-aware at runtime. */
 47	  privacyPolicyHref?: string;
 48	};
 49	
 50	// ---------------------------------------------------------------------------
 51	// Footer
 52	// ---------------------------------------------------------------------------
 53	
 54	/**
 55	 * Zimmermann global footer — presentational. Receives its content as props and fetches
 56	 * nothing, matching every other Contentful-backed component in the repo (`DuplexSection`,
 57	 * `HeroBanner`, `ProductHero`, `VideoEmbed`).
 58	 *
 59	 * Composed from independently-exported organisms/molecules (ui-kits/organisms/
 60	 * zimmSubscribeSection, ui-kits/molecules/zimmContactIconRow via FooterNavColumn) rather than
 61	 * defining them inline — see .claude/rules/overrideStyling.md for the reasoning. This file owns
 62	 * only the footer's own shell layout: content row, nav-column wrapper, logo band, bottom bar.
 63	 *
 64	 * `data` is required by design: static content belongs in the story or in the container below,
 65	 * never baked into the component that renders production UI. Omneo email submit and Cookie
 66	 * Settings are separate stories (HPC-035, HPC-038).
 67	 */
 68	export const Footer = ({
 69	  data,
 70	  copyrightYear = new Date().getFullYear(),
 71	  initialSubscribed = false,
 72	  privacyPolicyHref = '#',
 73	  onLogoClick = noop,
 74	  enableNameCapture = false,
 75	}: FooterProps) => {
 76	  const {
 77	    subscribeHeading,
 78	    subscribeBody,
 79	    navGroups,
 80	    legalLinks = [],
 81	    copyrightOwner,
 82	    phoneHref,
 83	    whatsAppHref,
 84	    emailHref,
 85	  } = data.fields;
 86	
 87	  const legalItems = legalLinks.map((e) => ({ label: e.fields.label, href: e.fields.href }));
 88	  const styles = useMultiStyleConfig(ZIMM_FOOTER_RECIPE, {});
 89	
 90	  return (
 91	    <chakra.footer role="contentinfo" __css={styles.container}>
 92	      <chakra.div __css={styles.main}>
 93	        <chakra.div __css={styles.contentRow}>
 94	          <chakra.div __css={styles.subscribe}>
 95	            <ZimmSubscribeSection
 96	              heading={subscribeHeading ?? ''}
 97	              body={subscribeBody ?? ''}
 98	              initialSubscribed={initialSubscribed}
 99	              privacyPolicyHref={privacyPolicyHref}
100	              enableNameCapture={enableNameCapture}
101	            />
102	          </chakra.div>
103	
104	          <chakra.div __css={styles.links}>
105	            <chakra.div __css={styles.linksInner}>
106	              {navGroups.map((group) => (
107	                <FooterNavColumn
108	                  key={group.sys.id}
109	                  group={group}
110	                  phoneHref={phoneHref}
111	                  whatsAppHref={whatsAppHref}
112	                  emailHref={emailHref}
113	                />
114	              ))}
115	            </chakra.div>
116	          </chakra.div>
117	        </chakra.div>
118	
119	        <chakra.div __css={styles.logo}>
120	          {/* Button + programmatic nav, matching the header's wordmark rather than an <a href>.
121	              The handler comes from FooterContainer — see the note there on why it uses
122	              buildUrl + history.push rather than useNavigation. styles.logoButton is a chrome
123	              reset only, so the logo keeps its own geometry. */}
124	          <chakra.button type="button" aria-label="Zimmermann home" onClick={onLogoClick} __css={styles.logoButton}>
125	            <ZimmLogo variant="inverse" />
126	          </chakra.button>
127	        </chakra.div>
128	      </chakra.div>
129	
130	      <BottomBar copyrightYear={copyrightYear} copyrightOwner={copyrightOwner ?? ''} legalLinks={legalItems} />
131	    </chakra.footer>
132	  );
133	};
134	
135	// ---------------------------------------------------------------------------
136	// Container — the default export
137	// ---------------------------------------------------------------------------
138	
139	/**
140	 * Contentful's `include`-resolved response nests navGroups/links/regions but applies no
141	 * region scoping of its own — narrow each region-aware array down to the current
142	 * storefront via the shared resolveByRegion utilities.
143	 */
144	export const scopeToRegion = (config: FooterConfigEntry, siteId: string): FooterConfigEntry => {
145	  const navGroups: FooterNavGroupEntry[] = config.fields.navGroups.map(
146	    (group): FooterNavGroupEntry => ({
147	      ...group,
148	      fields: { ...group.fields, links: filterByRegion<LinkEntry>(group.fields.links, siteId) },
149	    }),
150	  );
151	  const legalLinks: LinkEntry[] | undefined = config.fields.legalLinks
152	    ? filterByRegion<LinkEntry>(config.fields.legalLinks, siteId)
153	    : undefined;
154	
155	  return { ...config, fields: { ...config.fields, navGroups, legalLinks } };
156	};
157	
158	/**
159	 * The component SFCC actually renders. Base `_app/index.jsx` resolves
160	 * `@salesforce/retail-react-app/app/components/footer` through the overrides system and renders
161	 * `<Footer />` with **no props**, so there is no upstream container to own the data. This
162	 * wrapper is that seam, and the only place the Contentful fetch lives.
163	 *
164	 * HPC-034: fetches `footerConfig` entries via the Delivery API, then picks the entry scoped
165	 * to the current storefront's region (falls back to the global/unscoped entry once one
166	 * exists). Renders nothing while loading, on fetch failure, or when no entry resolves for
167	 * this region — no fallback to placeholder content once wired to live data, so a Contentful
168	 * outage doesn't silently ship stale placeholder copy to real shoppers. Note this puts a
169	 * fetch inside `components/`, which components.md reserves for containers; if that matters,
170	 * this should move into an `_app` override instead (Tier 2 shared shell — coordinate first).
171	 */
172	const FooterContainer = (props: Omit<FooterProps, 'data'>) => {
173	  // buildUrl + history.push, not useNavigation. useNavigation special-cases the home path
174	  // (`path === '/' ? '/' : updatedHref`), so navigate('/') pushes a bare '/' and skips the
175	  // site/locale prefix — on a prefixed storefront that drops the shopper onto the default
176	  // site. This is the exact pair base _app's onLogoClick uses, so both wordmarks resolve home
177	  // the same way on every storefront.
178	  //
179	  // useMultiSite ships untyped from the base SFCC package. site.id here is the resolved
180	  // SFCC site ID — confirmed against useCountryConfig.ts's identical client-side pattern
181	  // (`c.sfccSiteId === site?.id`), the existing precedent for this exact lookup.
182	  const { site, buildUrl } = useMultiSite() as {
183	    site: { id: string };
184	    buildUrl: (path: string, siteRef?: string, localeRef?: string) => string;
185	  };
186	  const history = useHistory();
187	  const { client } = useContentfulClient();
188	  const [footerData, setFooterData] = useState<FooterConfigEntry | null>(null);
189	
190	  useEffect(() => {
191	    if (!client) return;
192	    let cancelled = false;
193	
194	    client
195	      .getEntries({ content_type: 'footerConfig', include: FOOTER_INCLUDE_DEPTH })
196	      .then((response) => {
197	        if (cancelled) return;
198	        // The contentful SDK client is loosely typed (see useContentfulClient.ts) —
199	        // FooterConfigEntry mirrors the exact nested-resolved shape `include: 3` produces
200	        // for this content model.
201	        const configs = response.items as unknown as FooterConfigEntry[];
202	        const resolved = pickMostSpecificByRegion<FooterConfigEntry>(configs, site.id);
203	        setFooterData(resolved ? scopeToRegion(resolved, site.id) : null);
204	      })
205	      .catch(() => {
206	        if (!cancelled) setFooterData(null);
207	      });
208	
209	    return () => {
210	      cancelled = true;
211	    };
212	  }, [client, site.id]);
213	
214	  if (!footerData) return null;
215	
216	  return <Footer data={footerData} onLogoClick={() => history.push(buildUrl(HOME_HREF))} {...props} />;
217	};
218	
219	export default FooterContainer;

