     1	#!/usr/bin/env node
     2	/**
     3	 * Populate .env with Contentful API tokens fetched live from the space.
     4	 *
     5	 * Rules:
     6	 *   - Missing var  → added at the end of the Contentful block
     7	 *   - Empty var    → filled with the live value
     8	 *   - Wrong var    → updated with the live value
     9	 *   - CONTENTFUL_MANAGEMENT_TOKEN → never touched (per-user personal token)
    10	 *
    11	 * Write access (add/update) is gated to @ZimmermannAU/tier-1-approvers.
    12	 * Non-approvers get a read-only view of what the values should be.
    13	 *
    14	 * Usage:
    15	 *   npm run config:contentful               # update .env if authorised
    16	 *   npm run config:contentful -- --dry-run  # print changes without writing
    17	 */
    18	
    19	import { readFileSync, writeFileSync, existsSync } from 'fs';
    20	import { execSync } from 'child_process';
    21	import { resolve, dirname } from 'path';
    22	import { fileURLToPath } from 'url';
    23	import { checkEnv, createClient, log } from './_shared.mjs';
    24	
    25	const __dirname = dirname(fileURLToPath(import.meta.url));
    26	const REPO_ROOT = resolve(__dirname, '../../../');
    27	const ENV_FILE = resolve(REPO_ROOT, '.env');
    28	const DRY_RUN = process.argv.includes('--dry-run');
    29	
    30	const ENVIRONMENT_IDS = ['master', 'dev', 'test', 'sit', 'staging', 'uat'];
    31	const SKIP_VARS = new Set(['CONTENTFUL_MANAGEMENT_TOKEN']);
    32	
    33	// Vars managed by this script, keyed by their .env name
    34	const MANAGED_VARS = [
    35	  'CONTENTFUL_SPACE_ID',
    36	  'CONTENTFUL_ENVIRONMENT_ID',
    37	  'CONTENTFUL_DELIVERY_TOKEN',
    38	  'CONTENTFUL_PREVIEW_TOKEN',
    39	];
    40	
    41	checkEnv(['CONTENTFUL_MANAGEMENT_TOKEN', 'CONTENTFUL_SPACE_ID']);
    42	
    43	// ── Tier 1 gate ──────────────────────────────────────────────────────────────
    44	
    45	async function isTier1Approver() {
    46	  try {
    47	    const login = execSync('gh api user --jq .login', { encoding: 'utf8' }).trim();
    48	    const membersRaw = execSync(
    49	      "gh api orgs/ZimmermannAU/teams/tier-1-approvers/members --jq '.[].login'",
    50	      { encoding: 'utf8' },
    51	    ).trim();
    52	    const members = membersRaw.split('\n').filter(Boolean);
    53	    return { approved: members.includes(login), login };
    54	  } catch {
    55	    return { approved: false, login: 'unknown' };
    56	  }
    57	}
    58	
    59	// ── .env parsing ─────────────────────────────────────────────────────────────
    60	
    61	function parseEnv(content) {
    62	  return content.split('\n').map((line) => {
    63	    if (line.startsWith('#') || line.trim() === '') {
    64	      return { type: 'raw', value: line };
    65	    }
    66	    const eqIdx = line.indexOf('=');
    67	    if (eqIdx === -1) return { type: 'raw', value: line };
    68	    return { type: 'var', key: line.slice(0, eqIdx), value: line.slice(eqIdx + 1) };
    69	  });
    70	}
    71	
    72	function serializeEnv(entries) {
    73	  return entries.map((e) => (e.type === 'var' ? `${e.key}=${e.value}` : e.value)).join('\n');
    74	}
    75	
    76	// ── Main ─────────────────────────────────────────────────────────────────────
    77	
    78	async function main() {
    79	  const { approved, login } = await isTier1Approver();
    80	
    81	  if (!approved) {
    82	    log.warn(`Authenticated as '${login}' — not a tier-1-approver. Running in read-only mode.`);
    83	  } else {
    84	    log.info(`Authenticated as '${login}' (tier-1-approver). Write access granted.`);
    85	  }
    86	
    87	  const canWrite = approved && !DRY_RUN;
    88	  if (DRY_RUN) log.info('Dry-run flag set — no writes will occur.');
    89	
    90	  // Fetch live config from Contentful
    91	  const client = createClient();
    92	  const spaceId = process.env.CONTENTFUL_SPACE_ID;
    93	
    94	  log.section('Fetching live API keys from Contentful');
    95	  const { items: apiKeys } = await client.apiKey.getMany({ query: { limit: 100 } });
    96	
    97	  // Build a map: environmentId → { deliveryToken, previewToken }
    98	  const tokenMap = {};
    99	  for (const key of apiKeys) {
   100	    const envLink = key.environments?.[0];
   101	    if (!envLink) continue;
   102	    const envId = envLink.sys.id;
   103	
   104	    // Fetch the linked preview key
   105	    let previewToken = '';
   106	    if (key.preview_api_key?.sys?.id) {
   107	      try {
   108	        const previewKey = await client.previewApiKey.get({
   109	          previewApiKeyId: key.preview_api_key.sys.id,
   110	        });
   111	        previewToken = previewKey.accessToken;
   112	      } catch {
   113	        // non-fatal — preview key may not exist yet
   114	      }
   115	    }
   116	
   117	    tokenMap[envId] = { deliveryToken: key.accessToken, previewToken };
   118	  }
   119	
   120	  // .env update logic
   121	  if (!existsSync(ENV_FILE)) {
   122	    log.error('.env file not found at repo root. Create it from .env.sample first.');
   123	    process.exit(1);
   124	  }
   125	
   126	  const raw = readFileSync(ENV_FILE, 'utf8');
   127	  const entries = parseEnv(raw);
   128	  const changes = [];
   129	
   130	  function upsertVar(key, value) {
   131	    if (SKIP_VARS.has(key)) return;
   132	    const existing = entries.find((e) => e.type === 'var' && e.key === key);
   133	    if (!existing) {
   134	      entries.push({ type: 'var', key, value });
   135	      changes.push({ action: 'add', key, value });
   136	    } else if (!existing.value) {
   137	      existing.value = value;
   138	      changes.push({ action: 'fill', key, value });
   139	    } else if (existing.value !== value) {
   140	      existing.value = value;
   141	      changes.push({ action: 'update', key, value });
   142	    }
   143	  }
   144	
   145	  // Always ensure CONTENTFUL_SPACE_ID is correct
   146	  upsertVar('CONTENTFUL_SPACE_ID', spaceId);
   147	
   148	  // Populate tokens for the local dev environment
   149	  const localEnvId = process.env.CONTENTFUL_ENVIRONMENT_ID || 'dev';
   150	  const localTokens = tokenMap[localEnvId];
   151	  if (localTokens) {
   152	    upsertVar('CONTENTFUL_DELIVERY_TOKEN', localTokens.deliveryToken);
   153	    upsertVar('CONTENTFUL_PREVIEW_TOKEN', localTokens.previewToken);
   154	  } else {
   155	    log.warn(`No API key found for environment '${localEnvId}'. Run setup:contentful first.`);
   156	  }
   157	
   158	  // Print the full token map for all environments (always shown, regardless of write access)
   159	  log.section('Live token values per environment');
   160	  for (const envId of ENVIRONMENT_IDS) {
   161	    const tokens = tokenMap[envId];
   162	    if (!tokens) {
   163	      log.warn(`${envId}: no API key found (run setup:contentful)`);
   164	    } else {
   165	      console.log(`  ${envId.padEnd(10)} delivery: ${tokens.deliveryToken.slice(0, 8)}…  preview: ${tokens.previewToken ? tokens.previewToken.slice(0, 8) + '…' : '(none)'}`);
   166	    }
   167	  }
   168	
   169	  if (changes.length === 0) {
   170	    log.success('.env is already up to date.');
   171	    return;
   172	  }
   173	
   174	  log.section('Changes');
   175	  for (const c of changes) {
   176	    const label = c.action === 'add' ? '+ add  ' : c.action === 'fill' ? '~ fill ' : '~ update';
   177	    console.log(`  ${label}  ${c.key}`);
   178	  }
   179	
   180	  if (!canWrite) {
   181	    log.warn(approved ? 'Dry-run — no writes made.' : 'Read-only — contact a tier-1-approver to apply these changes.');
   182	    return;
   183	  }
   184	
   185	  writeFileSync(ENV_FILE, serializeEnv(entries), 'utf8');
   186	  log.success(`.env updated (${changes.length} change${changes.length === 1 ? '' : 's'}).`);
   187	}
   188	
   189	main().catch((err) => {
   190	  log.error(err.message ?? err);
   191	  process.exit(1);
   192	});

